"use strict";(self.webpackChunkmocpilot_docs=self.webpackChunkmocpilot_docs||[]).push([[5420],{6888:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/08/23/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/08/23/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-08-23-post.md","title":"Udgivelse MOCPilot 2026.5.0","description":"\ud83d\ude80 MOCPilot 2026.5.0 \u2014 Firmwareopdateringer, SBrick-support og konstrukt\xf8rforbedringer","date":"2026-08-23T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":1.15,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2026.5.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"nextItem":{"title":"Udgivelse af MOCPilot 2026.4.0","permalink":"/mocpilot-app-docs/dk/blog/2026/06/06/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.5.0 \u2014 Firmwareopdateringer, SBrick-support og konstrukt\xf8rforbedringer\\r\\n\\r\\nVi er glade for at annoncere **MOCPilot 2026.5.0**, tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne opdatering tilf\xf8jer firmwareopdatering og gendannelse for flere LEGO Powered Up hubs, introducerer support for SBrick og SBrick Plus, forbedrer blokbyggeren og kontrolpanelets arbejdsgang og indeholder mange brugerfladeforbedringer, nedbrudsrettelser og overs\xe6ttelsesopdateringer.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.5.0?\\r\\n\\r\\n### \ud83d\udd04 Firmwareopdatering og gendannelse af hubs\\r\\n\\r\\n- Tilf\xf8jet firmwareopdatering for **Technic Hub**\\r\\n- Tilf\xf8jet firmwareopdatering for **Technic Move Hub**\\r\\n- Udvidet firmwareopdatering for flere underst\xf8ttede hubs\\r\\n- Tilf\xf8jet registrering af hubs forbundet i **gendannelsestilstand**\\r\\n\\r\\n### \ud83d\udd0c Hub-support og konfiguration\\r\\n\\r\\n- Tilf\xf8jet support for **SBrick** og **SBrick Plus**\\r\\n- Tilf\xf8jet konfigurations\xe6ndring for Technic Move Hub: **Porsche GT4 e-Performance**, **Batmobile\u2122\u200e Tumbler** og **Lamborghini Revuelto**\\r\\n- Omarbejdet hub-forbindelsessider efter forbindelsestype\\r\\n- Omarbejdet hub-monitoreringssiden\\r\\n\\r\\n### \ud83e\uddf1 Opdateringer til blokbyggeren\\r\\n\\r\\n- Tilf\xf8jet filtrering efter blokniveauer: **Beginner**, **Advanced** og **Guru**\\r\\n- Blokniveauer kan konfigureres, n\xe5r et profil-block program oprettes, redigeres eller k\xf8res\\r\\n- Tilf\xf8jet **batterisp\xe6nding**-blok for hubs, der leverer batterisp\xe6ndingsdata\\r\\n- Tilf\xf8jet **effektimpuls**-blok for Technic Move Hub\\r\\n- Rettet skalering med musehjul p\xe5 blokpaletten\\r\\n\\r\\n### \ud83c\udfae Gamepad og kontrolpanel\\r\\n\\r\\n- Omarbejdet gamepad-siden og gamepadtestersiden\\r\\n- Rettet tilstandsovergange for gamepaddets D-pad\\r\\n- Tilf\xf8jet en kontekstmenuindstilling til at \xe6ndre temaet for kontrolpanelets element direkte\\r\\n- Forbedret kontrolpanelets profiloverskrifter, sorteringsmenu, kortgradienter og afstand i oprettelsesformularen\\r\\n\\r\\n### \ud83c\udfa8 Brugerflade, profiler og stabilitet\\r\\n\\r\\n- Fjernet den gule palette fra forudbyggede profiler, s\xe5 de nu matcher den almindelige profilsiden\\r\\n- Forbedret det generelle udseende og mindre brugerfladedetaljer\\r\\n- Tilf\xf8jet nedbrudsrettelser og intern kodeomorganisering"},{"id":"/2026/06/06/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/06/06/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-06-06-post.md","title":"Udgivelse af MOCPilot 2026.4.0","description":"\ud83d\ude80 MOCPilot 2026.4.0 \u2014 Fortryd/Gentag, hub-profiler og byggerrettelser","date":"2026-06-06T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":0.73,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse af MOCPilot 2026.4.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2026.5.0","permalink":"/mocpilot-app-docs/dk/blog/2026/08/23/post"},"nextItem":{"title":"Release MOCPilot 2026.3.2","permalink":"/mocpilot-app-docs/dk/blog/2026/05/02/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.4.0 \u2014 Fortryd/Gentag, hub-profiler og byggerrettelser\\r\\n\\r\\nVi er glade for at kunne annoncere udgivelsen af **MOCPilot 2026.4.0**, som er tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne opdatering tilf\xf8jer fortryd- og gentag-historik til blokprogrammer, forbedrer hub-ops\xe6tning i profilbyggeren og retter flere problemer i byggeren og enhedsstyringen.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.4.0?\\r\\n\\r\\n### \ud83e\uddf1 Historik for blokprogrammer\\r\\n\\r\\n- Tilf\xf8jet **historikstyring for fortryd og gentag** i blokprogrammer\\r\\n\\r\\n### \ud83d\udd0c Profilbygger for hubs\\r\\n\\r\\n- **Tilf\xf8jelse af hub** er adskilt fra forbindelsesflowet i profilbyggeren\\r\\n- Hubs kan nu tilf\xf8jes til en profil uden krav om \xf8jeblikkelig forbindelse\\r\\n\\r\\n### \ud83d\udee0 Bygger- og enhedsrettelser\\r\\n\\r\\n- Rettet den oversatte kontekstmenutekst **delete-blocks**\\r\\n- Rettet **kommandotilknytning for WeDo 2.0-motorporte**, s\xe5 styring gendannes ved brug af en af to motorporte\\r\\n- Rettet et problem med blokkenes **forreste samlingstype**, s\xe5 fastg\xf8relse mellem disse blokke nu fungerer korrekt\\r\\n\\r\\n---\\r\\n\\r\\nOpdater til **2026.4.0** for bedre blokredigering, mere fleksibel hub-ops\xe6tning og forbedret WeDo 2.0-motorstyring."},{"id":"/2026/05/02/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/05/02/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-05-02-post.md","title":"Release MOCPilot 2026.3.2","description":"\ud83d\ude80 MOCPilot 2026.3.2 \u2014 Dashboard-controller-ikoner og Builder-rettelser","date":"2026-05-02T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":0.7,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Release MOCPilot 2026.3.2","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse af MOCPilot 2026.4.0","permalink":"/mocpilot-app-docs/dk/blog/2026/06/06/post"},"nextItem":{"title":"Udgivelse af MOCPilot 2026.3.1","permalink":"/mocpilot-app-docs/dk/blog/2026/04/18/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.3.2 \u2014 Dashboard-controller-ikoner og Builder-rettelser\\r\\n\\r\\nVi er glade for at kunne annoncere udgivelsen af **MOCPilot 2026.3.2**, som er tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne opdatering forbedrer dashboard-controllernes visuelle udtryk, retter flere interaktionsproblemer i builderen og finjusterer kalibreringen af styret\xf8jsstangen.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.3.2?\\r\\n\\r\\n### \ud83c\udf9b Dashboard-controller-forbedringer\\r\\n\\r\\n- Tilf\xf8jet **nye ikoner** til dashboard-controllere\\r\\n\\r\\n### \ud83e\uddf1 Builder- og blokrettelser\\r\\n\\r\\n- Rettet et problem, hvor h\xe6ndelsen **Hub-tilt \xe6ndret** kunne blive udl\xf8st forkert p\xe5 grund af sammenligning mellem heltal og decimaltal\\r\\n- Rettet problemer med **blok-tilknytning ved tr\xe6k**, som p\xe5virkede **C-blokke** og andre bloktyper\\r\\n\\r\\n### \u2699\ufe0f Opdatering af styrekalibrering\\r\\n\\r\\n- Blokken **Kalibr\xe9r styret\xf8jsstang** er blevet omarbejdet\\r\\n- Blokken nulstiller nu den **relative position til `0`**, n\xe5r kalibreringen er f\xe6rdig\\r\\n- Hastigheden i kalibreringsalgoritmen er \xe6ndret til **100**\\r\\n\\r\\n---\\r\\n\\r\\nOpdater til **2026.3.2** for mere smidig blokbygning, forbedret udseende af dashboard-controllere og mere p\xe5lidelig styrekalibrering."},{"id":"/2026/04/18/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/04/18/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-04-18-post.md","title":"Udgivelse af MOCPilot 2026.3.1","description":"\ud83d\ude80 MOCPilot 2026.3.1 \u2014 Gamepad- og Builder-opdatering","date":"2026-04-18T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":1.38,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse af MOCPilot 2026.3.1","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Release MOCPilot 2026.3.2","permalink":"/mocpilot-app-docs/dk/blog/2026/05/02/post"},"nextItem":{"title":"Udgivelse af MOCPilot 2026.2.3","permalink":"/mocpilot-app-docs/dk/blog/2026/02/28/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.3.1 \u2014 Gamepad- og Builder-opdatering\\r\\n\\r\\nVi er glade for at kunne annoncere **MOCPilot 2026.3.1**, tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne udgivelse bringer store forbedringer til block builderen (touch + desktop) og st\xe6rkere gamepad-underst\xf8ttelse.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.3.1?\\r\\n\\r\\n### \ud83c\udfae Gamepad-forbedringer\\r\\n\\r\\n- Gamepad-blokke **aktiveres automatisk**, n\xe5r en profil \xe5bnes (ogs\xe5 hvis en gamepad allerede er tilsluttet)\\r\\n- Rettet et problem hvor **gamepad-eventblokke tilf\xf8jet senere** f\xf8rst blev aktive efter genstart af programmet\\r\\n- Tilf\xf8jet indstilling for **gamepad-v\xe6rdomr\xe5de** for finere kontrol\\r\\n\\r\\n### \ud83e\uddf1 Builder- og editorforbedringer\\r\\n\\r\\n- Stor pakke forbedringer af **touch-gester** og den generelle interaktion (mobil + desktop)\\r\\n- Mere p\xe5lidelig **fortryd/historik** (pt. **kun dashboard**), med en omarbejdet historik der sporer \xe6ndringer, s\xe5 du mere konsekvent kan vende tilbage til en tidligere tilstand\\r\\n- Rettet flere problemer i **port-editoren** og v\xe6rdi-redigering p\xe5 mobile enheder\\r\\n- Rettet et problem p\xe5 mobil hvor pinch-gester kunne f\xe5 **programomr\xe5det til at s\xe6tte sig fast**\\r\\n- Forbedret block snapping og inds\xe6ttelses-preview n\xe5r du bygger kontrolstrukturer\\r\\n- Tilf\xf8jet en **halo** for k\xf8rende blokke\\r\\n\\r\\n\\r\\n### \ud83d\udd0c Hub og forbindelser\\r\\n\\r\\n- **Hub-knapv\xe6lgeren** i den relevante blok er nu **altid synlig**, med omarbejdet ops\xe6tning af knap-events\\r\\n\\r\\n### \ud83e\udde9 Palette og hj\xe6lp\\r\\n\\r\\n- Rettet palette-problemer efter **sprog/locale-skift** (palette-handlingsknapper kunne blive inaktive)\\r\\n- Tilf\xf8jet kontekstmenuvalget **\u201cAbout Block\u201d** til at \xe5bne dokumentation for den valgte blok\\r\\n\\r\\n### \ud83d\udcda Hj\xe6lp-opdateringer\\r\\n\\r\\n- Hj\xe6lpesider udvidet med **direkte links til blok-dokumentation**\\r\\n\\r\\n### \ud83e\udd16 Android-rettelser\\r\\n\\r\\n- Rettet problemer med **deling og import af profiler** p\xe5 Android\\r\\n\\r\\n### \ud83d\udee0 Rendering og ydeevne\\r\\n\\r\\n- Rettet **sl\xf8rede/ikke-skarpe blokke** ved h\xf8j skala ved at omarbejde rendererens teksturh\xe5ndtering\\r\\n- Optimeret **texture upscaler** til mobile enheder og forbedret afstand/zoom-adf\xe6rd i programomr\xe5det\\r\\n\\r\\n---\\r\\n\\r\\nOpdater til **2026.3.1** for en meget mere flydende builder-oplevelse og bedre gamepad-workflows."},{"id":"/2026/02/28/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/02/28/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-02-28-post.md","title":"Udgivelse af MOCPilot 2026.2.3","description":"\ud83d\ude80 MOCPilot 2026.2.3 \u2014 Dashboard- og hubrettelser","date":"2026-02-28T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":0.86,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse af MOCPilot 2026.2.3","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse af MOCPilot 2026.3.1","permalink":"/mocpilot-app-docs/dk/blog/2026/04/18/post"},"nextItem":{"title":"Udgivelse MOCPilot 2026.2.2","permalink":"/mocpilot-app-docs/dk/blog/2026/02/18/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.2.3 \u2014 Dashboard- og hubrettelser\\r\\n\\r\\nVi er glade for at kunne annoncere **MOCPilot 2026.2.3**, tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne opdatering forbedrer dashboard-arbejdsgangen og retter flere vigtige problemer med hubs og editoren.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.2.3?\\r\\n\\r\\n### \ud83e\uddf1 Dashboard-forbedringer\\r\\n\\r\\n- Du kan nu **duplikere dashboard-controllere**, med mulighed for at **kopiere alle egenskaber** eller **kun kopiere efter type**\\r\\n- **Paletten er omarbejdet** for hurtigere opbygning: vises under dashboardet, har en ryd-knap, lukker ikke efter tilf\xf8jelse af komponenter og holder sektionsvalget konsistent\\r\\n\\r\\n### \ud83d\udd0c Hub-opdateringer og rettelser\\r\\n\\r\\n- **Mould King 4.0** reimplementeret til **den nye protokol p\xe5 iOS** (Android bruger fortsat den tidligere protokol)\\r\\n- Rettet et problem hvor den **boolske blok \u201chub er forbundet\u201d** ikke blev vist mens hubben annoncerede\\r\\n- Rettet en fejl hvor **lys-blokken** kunne stoppe med at virke p\xe5 grund af h\xe5ndtering af motor start/stop-kommandoer\\r\\n\\r\\n### \ud83d\udee0 Rettelser\\r\\n\\r\\n- Rettet e-mailvalidering i input-komponenten, som kunne tillade ugyldige adresser som `mail@domain.`\\r\\n\\r\\n---\\r\\n\\r\\nOpdater til **2026.2.3** for en mere glidende dashboard-oplevelse og mere stabile hubs p\xe5 tv\xe6rs af platforme."},{"id":"/2026/02/18/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/02/18/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-02-18-post.md","title":"Udgivelse MOCPilot 2026.2.2","description":"\ud83d\ude80 MOCPilot 2026.2.2 \u2014 Udvidet hub- og kontrolopdatering","date":"2026-02-18T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":1.01,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2026.2.2","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse af MOCPilot 2026.2.3","permalink":"/mocpilot-app-docs/dk/blog/2026/02/28/post"},"nextItem":{"title":"Udgivelse MOCPilot 2026.1.0","permalink":"/mocpilot-app-docs/dk/blog/2026/01/10/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.2.2 \u2014 Udvidet hub- og kontrolopdatering\\r\\n\\r\\nVi er glade for at kunne annoncere udgivelsen af **MOCPilot 2026.2.2**, nu tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne version udvider hardwarekompatibiliteten markant og introducerer kraftfulde nye programmeringsblokke til avanceret hub-interaktion.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.2.2?\\r\\n\\r\\n### \ud83c\udd95 Ny hub-underst\xf8ttelse\\r\\n\\r\\n- **Mould King 4.0 hubs** er nu fuldt underst\xf8ttet  \\r\\n- **Mould King 6.0 hubs** er nu fuldt underst\xf8ttet  \\r\\n- **LEGO WeDo 2.0 hub** er nu fuldt underst\xf8ttet  \\r\\n\\r\\n---\\r\\n\\r\\n### \ud83d\udd0c Sensorunderst\xf8ttelse\\r\\n\\r\\n- WeDo 2.0 h\xe6ldningssensor  \\r\\n- WeDo 2.0 bev\xe6gelsessensor\\r\\n\\r\\n---\\r\\n\\r\\n### \ud83e\uddf1 Nye programmeringsblokke\\r\\n\\r\\nDenne version introducerer nye h\xe6ndelses- og kontrolblokke, der udvider mulighederne for realtidsinteraktion med hubs.\\r\\n\\r\\n#### \ud83d\udd04 Hub-sensor h\xe6ndelsesblokke\\r\\n- **Hub accelerometerdata \xe6ndret**  \\r\\n- **Hub h\xe6ldning \xe6ndret**  \\r\\n- **Hub orientering \xe6ndret**  \\r\\n- **Alle hubs batteriniveau \xe6ndret**\\r\\n\\r\\nDisse blokke g\xf8r det muligt for dit program straks at reagere p\xe5 bev\xe6gelse, rotation og \xe6ndringer i str\xf8m.\\r\\n\\r\\n#### \ud83d\udd0c Hub-forbindelseskontrolblokke\\r\\n- **Forbind hub**\\r\\n- **Afbryd hub**\\r\\n\\r\\nDu kan nu administrere hub-forbindelser direkte under programk\xf8rsel.  \\r\\nDette g\xf8r det muligt at genoprette forbindelsen til en hub uden at genstarte programmet, hvis forbindelsen mistes, hvilket g\xf8r projekter mere robuste og fleksible.\\r\\n\\r\\n---\\r\\n\\r\\n### \u2699\ufe0f Forbedringer\\r\\n\\r\\n- Forbedret samlet systemstabilitet  \\r\\n- Ydelsesoptimeringer for mere j\xe6vn hub-interaktion  \\r\\n- Mindre UI- og layoutforbedringer  \\r\\n\\r\\n---\\r\\n\\r\\nOpdater MOCPilot til den nyeste version og begynd at bygge med udvidet hub-kompatibilitet og kraftfulde realtidskontrolfunktioner p\xe5 alle dine enheder."},{"id":"/2026/01/10/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2026/01/10/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2026-01-10-post.md","title":"Udgivelse MOCPilot 2026.1.0","description":"\ud83d\ude80 MOCPilot 2026.1.0 \u2014 Funktions- og stabilitetsopdatering","date":"2026-01-10T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":1.08,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2026.1.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2026.2.2","permalink":"/mocpilot-app-docs/dk/blog/2026/02/18/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.2.0 - 2025.2.4","permalink":"/mocpilot-app-docs/dk/blog/2025/12/28/post"}},"content":"## \ud83d\ude80 MOCPilot 2026.1.0 \u2014 Funktions- og stabilitetsopdatering\\r\\n\\r\\nVi er glade for at annoncere udgivelsen af **MOCPilot 2026.1.0**, nu tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne udgivelse introducerer **g\xe6stetilstand**, forbedrer brugervenligheden p\xe5 mobile enheder og leverer vigtige stabilitets- og ydeevnefix p\xe5 tv\xe6rs af alle platforme.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er nyt i 2026.1.0?\\r\\n\\r\\n### \ud83c\udd95 Nyt\\r\\n- **G\xe6stetilstand** \u2014 brug appen uden en konto, med mulighed for at oprette en senere\\r\\n- Sprogvalg tilf\xf8jet p\xe5 login-/godkendelsessk\xe6rmen\\r\\n- Appen blokerer nu brug af hubs med firmware, der ikke underst\xf8ttes, og viser en tydelig advarsel\\r\\n\\r\\n### \u2699\ufe0f Forbedringer\\r\\n- Forbedret blok-tr\xe6kning p\xe5 mobile enheder (bedre touch-h\xe5ndtering, f\xe6rre utilsigtede interaktioner)\\r\\n- Blokpaletten skjules nu automatisk under tr\xe6k p\xe5 mobil\\r\\n- Advarselsdialoger anvender nu sl\xf8ring af baggrunden\\r\\n- Forbedret tekstinput p\xe5 tv\xe6rs af alle platforme\\r\\n- Mere j\xe6vn hub-styring med reduceret latenstid\\r\\n\\r\\n### \ud83d\udee0 Rettelser\\r\\n- Rettet flere problemer med blok drag & drop, inkl. fastl\xe5ste blokke og mistet mus/touch-input\\r\\n- Rettet nedbrud ved stop af programmer, der bruger brugerdefinerede (\u201cMy\u201d) blokke\\r\\n- Rettet at kalibrering af styrestang (steering rack) ikke vendte tilbage til midten\\r\\n- Rettet lag i hub-styring og forsinket motorrespons\\r\\n- Rettet problemer med editor-porte, sliders og hastighedsv\xe6rdi-blokke\\r\\n- Rettet problem med hoveddialogen og diverse UI-layout-fejl\\r\\n- Opdaterede overs\xe6ttelser og rettede mindre visuelle uoverensstemmelser\\r\\n\\r\\n---\\r\\n\\r\\nOpdater MOCPilot til den nyeste version og f\xe5 en mere glidende, stabil og tilg\xe6ngelig oplevelse p\xe5 alle dine enheder."},{"id":"/2025/12/28/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/12/28/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-12-28-post.md","title":"Udgivelse MOCPilot 2025.2.0 - 2025.2.4","description":"\ud83d\ude80 MOCPilot 2025.2.0 - 2025.2.4 \u2014 Stabilitets- og oplevelsesopdatering","date":"2025-12-28T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":0.62,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.2.0 - 2025.2.4","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2026.1.0","permalink":"/mocpilot-app-docs/dk/blog/2026/01/10/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.2.0","permalink":"/mocpilot-app-docs/dk/blog/2025/11/15/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.2.0 - 2025.2.4 \u2014 Stabilitets- og oplevelsesopdatering\\r\\n\\r\\nVi er glade for at annoncere **MOCPilot 2025.2.0 - 2025.2.4**, nu tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**.\\r\\n\\r\\nDenne udgivelse fokuserer p\xe5 **mere j\xe6vn funktion**, **forbedret stabilitet** og **UI-forbedringer** p\xe5 tv\xe6rs af alle platforme.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Hvad er forbedret i 2025.2.0 - 2025.2.4?\\r\\n\\r\\n- Mere j\xe6vn og stabil funktion takket v\xe6re forbedret tidslogik\\r\\n- Forbedret profilsynkronisering og opdateringsp\xe5lidelighed\\r\\n- Forbedret layout af profillisten med tydeligere information\\r\\n- Forbedrede visuelle effekter og interaktion for aura-slideren\\r\\n- Rettet problemer med pitch/roll-invertering i styring\\r\\n- Forbedrede UI-layouts p\xe5 telefoner og tablets\\r\\n- Rettet problemer med farver, kontakter og visuel konsistens\\r\\n- Forbedrede overs\xe6ttelser og tekstkonsistens\\r\\n- Generelle fejlrettelser, ydeevne- og stabilitetsforbedringer\\r\\n\\r\\n---\\r\\n\\r\\nOpdater MOCPilot til den nyeste version og f\xe5 en mere stabil og responsiv oplevelse p\xe5 alle dine enheder."},{"id":"/2025/11/15/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/11/15/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-11-15-post.md","title":"Udgivelse MOCPilot 2025.2.0","description":"\ud83d\ude80 MOCPilot 2025.2.0 \u2014 Officiel multiplatformudgivelse!","date":"2025-11-15T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"}],"readingTime":0.54,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.2.0","authors":["maxim"],"tags":["dev"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.2.0 - 2025.2.4","permalink":"/mocpilot-app-docs/dk/blog/2025/12/28/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.1.9","permalink":"/mocpilot-app-docs/dk/blog/2025/06/3/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.2.0 \u2014 Officiel multiplatformudgivelse!\\r\\n\\r\\nVi er glade for at kunne annoncere den officielle udgivelse af **MOCPilot 2025.2.0**, som nu er tilg\xe6ngelig p\xe5 **Android**, **iOS** og **macOS**!\\r\\n\\r\\nAppen, tidligere kendt som **Controlz**, har f\xe5et et nyt navn: **MOCPilot**.  \\r\\nDet nye navn afspejler bedre appens form\xe5l og fremtidige udvikling som en samlet \u201cpilot\u201d-platform til styring og programmering af dine LEGO\xae-kreationer.\\r\\n\\r\\n---\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## \u2728 Nyt i 2025.2.0\\r\\n\\r\\n- Samlet udgivelse til Android, iOS og macOS  \\r\\n- Forbedret stabilitet, ydeevne og UI-respons  \\r\\n- Opdateret branding og navn *MOCPilot*  \\r\\n- Fortsat support til LEGO\xae Control+, BuWizz 2/3 og brugerdefinerede Bluetooth-moduler  \\r\\n\\r\\n---\\r\\n\\r\\nDownload MOCPilot i dag og f\xe5 den n\xe6ste generations kontrol over dine LEGO\xae-modeller!"},{"id":"/2025/06/3/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/06/3/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-06-3-post.md","title":"Udgivelse MOCPilot 2025.1.9","description":"\ud83d\ude80 MOCPilot 2025.1.9 er nu tilg\xe6ngelig p\xe5 Mac App Store!","date":"2025-06-03T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.31,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.1.9","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.2.0","permalink":"/mocpilot-app-docs/dk/blog/2025/11/15/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.1.5","permalink":"/mocpilot-app-docs/dk/blog/2025/05/17/post"}},"content":"import { MacAppStoreBadge } from \'@site/src/pages/\';\\r\\n\\r\\n## \ud83d\ude80 MOCPilot 2025.1.9 er nu tilg\xe6ngelig p\xe5 Mac App Store!\\r\\n\\r\\nVi er glade for at kunne annoncere udgivelsen af MOCPilot 2025.1.9 som en native macOS-app!\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\nDu kan nu nyde fuld desktopydelse og problemfri integration med macOS.  \\r\\nDownload den i dag fra Mac App Store, og tag kontrol over dine LEGO\xae kreationer som aldrig f\xf8r!\\r\\n\\r\\n<MacAppStoreBadge/>"},{"id":"/2025/05/17/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/05/17/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-05-17-post.md","title":"Udgivelse MOCPilot 2025.1.5","description":"Beskrivelse","date":"2025-05-17T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.48,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.1.5","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.1.9","permalink":"/mocpilot-app-docs/dk/blog/2025/06/3/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.1.4","permalink":"/mocpilot-app-docs/dk/blog/2025/05/10/post"}},"content":"### Beskrivelse\\r\\n\\r\\nDenne opdatering forbedrer blokredigeringsoplevelsen, \xf8ger ydeevnen og sikrer korrekt funktionalitet p\xe5 nyere Android-versioner.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### \xc6ndringer\\r\\n\\r\\n- **Rettet en fejl med hub-scanning p\xe5 Android 12+** ved at anmode om pr\xe6cis lokationstilladelse.\\r\\n- **Tilf\xf8jet mulighed for at skjule/vis blokpaletten** ved at klikke p\xe5 den aktuelt valgte blok-samling.\\r\\n- **Tilf\xf8jet et st\xf8rreh\xe5ndtag** til blokpaletten for at tillade **manuel \xe6ndring af st\xf8rrelse**.\\r\\n- **Rettet h\xf8j CPU-brug** n\xe5r en profil var indl\xe6st, men programmet ikke k\xf8rte.\\r\\n- **Forbedret \\"String list\\" blokeditoren** for at undg\xe5, at indhold blev afsk\xe5ret. Nu er elementer opdelt i kolonner for bedre overskuelighed ved store lister."},{"id":"/2025/05/10/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/05/10/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-05-10-post.md","title":"Udgivelse MOCPilot 2025.1.4","description":"Beskrivelse","date":"2025-05-10T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.75,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.1.4","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.1.5","permalink":"/mocpilot-app-docs/dk/blog/2025/05/17/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.1.2 - 2025.1.3","permalink":"/mocpilot-app-docs/dk/blog/2025/04/19/post"}},"content":"### Beskrivelse\\r\\n\\r\\nDenne opdatering forbedrer supporten til tablets, tilf\xf8jer nyttige test-sider og retter flere kompatibilitets- og ydelsesproblemer.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### \xc6ndringer\\r\\n\\r\\n- **Tilf\xf8jet tablet-layout** for bedre udnyttelse af st\xf8rre sk\xe6rme.\\r\\n- **Rettet en fejl hvor blokken \\"hub button pressed\\"** dukkede op for hubs, der ikke underst\xf8tter denne handling. Rettet ogs\xe5 uhensigtsm\xe6ssige **farvesensorblokke** for ikke-underst\xf8ttede hubs (f.eks. BuWizz).\\r\\n- **Rettet en fejl hvor \\"motor run\\"-blokken** ikke p\xe5virkede motorer uden encodere pga. manglende alternative k\xf8rsel-kommandoer.\\r\\n- **Tilf\xf8jet en side til test af gamepad-knapper.**\\r\\n- **Tilf\xf8jet en hub-testside** med et dashboard, der viser information, tilsluttede porte-enheder og port-rystelsesstatus.\\r\\n- **Rettet forkert fortolkning af accelerometerdata** for BuWizz 2 og 3, som for\xe5rsagede fejlagtige orienteringsm\xe5linger.\\r\\n- **Rettet RAM-l\xe6kager** som f\xf8rte til app-nedlukning p\xe5 nogle enheder grundet h\xf8jt systemhukommelsesforbrug.\\r\\n- **Rettet fejl i profilindl\xe6sning** som tidligere kunne for\xe5rsage nedbrud i visse scenarier.\\r\\n- **Rettet en Android-fejl** hvor frigivelse af gamepad-sticks ikke nulstillede aksev\xe6rdier til nul."},{"id":"/2025/04/19/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/04/19/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-04-19-post.md","title":"Udgivelse MOCPilot 2025.1.2 - 2025.1.3","description":"Beskrivelse","date":"2025-04-19T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.41,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.1.2 - 2025.1.3","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.1.4","permalink":"/mocpilot-app-docs/dk/blog/2025/05/10/post"},"nextItem":{"title":"Udgivelse MOCPilot 2025.1.1","permalink":"/mocpilot-app-docs/dk/blog/2025/04/14/post"}},"content":"### Beskrivelse\\r\\n\\r\\nDenne opdatering introducerer nye muligheder for joystick-tilpasning, forbedringer i brugergr\xe6nsefladen og vigtige stabilitetsrettelser.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### \xc6ndringer\\r\\n\\r\\n- **L\xf8st en fejl i blokpalettens samlingsv\xe6lger**: at v\xe6lge en samling, scrolle til en anden og vende tilbage havde ingen effekt.\\r\\n- **L\xf8st en nedbrudsfejl ved indl\xe6sning af tunge profiler** med et stort antal blokke.\\r\\n- **Tilf\xf8jet egenskaben \u201cAxes type\u201d** til joystick-indstillinger for at underst\xf8tte **enkelt-akse-tilstand** (X, Y, XY).\\r\\n- **Tilf\xf8jet farvel\xe6gning** til rat-controllere (\u201cGMZ\u201d, \u201cNo Mercy\u201d).\\r\\n- **Tilf\xf8jet \u201cer trykket\u201d blokke** til rat og pedaler."},{"id":"/2025/04/14/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/04/14/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-04-14-post.md","title":"Udgivelse MOCPilot 2025.1.1","description":"Beskrivelse","date":"2025-04-14T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.43,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"Udgivelse MOCPilot 2025.1.1","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.1.2 - 2025.1.3","permalink":"/mocpilot-app-docs/dk/blog/2025/04/19/post"},"nextItem":{"title":"MOCPilot 2025.1.0","permalink":"/mocpilot-app-docs/dk/blog/2025/04/04/post"}},"content":"### Beskrivelse\\r\\n\\r\\nDenne opdatering indeholder flere vigtige fejlrettelser, der forbedrer ydeevnen, reducerer batteriforbruget og forbedrer blokadf\xe6rden i programmeringsmilj\xf8et.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n---\\r\\n\\r\\n### \xc6ndringer\\r\\n\\r\\n- **L\xf8st en fejl, der for\xe5rsagede h\xf8jt CPU-forbrug, batteridr\xe6n og lav ydeevne.**\\r\\n- **L\xf8st en fejl, hvor gamepad-blokke** (f.eks. \\"er knap trykket\\", \\"er D-PAD knap trykket\\") **ikke kunne forbindes til andre blokke.**\\r\\n- **L\xf8st et problem i step switch event-blokken**, som h\xe5ndterede touch-begivenheder og trinopt\xe6lling forkert.\\r\\n- **L\xf8st en fejl i listeblokkens \\"item of\\"**, hvor der ikke kunne tilknyttes mere end \xe9n blok som argumentindeks."},{"id":"/2025/04/04/post","metadata":{"permalink":"/mocpilot-app-docs/dk/blog/2025/04/04/post","source":"@site/i18n/dk/docusaurus-plugin-content-blog/2025-04-04-post.md","title":"MOCPilot 2025.1.0","description":"\ud83d\ude80 MOCPilot 2025.1.0 Lukket Beta er begyndt!","date":"2025-04-04T00:00:00.000Z","tags":[{"inline":false,"label":"Dev","permalink":"/mocpilot-app-docs/dk/blog/tags/dev","description":"Development news"},{"inline":false,"label":"Test","permalink":"/mocpilot-app-docs/dk/blog/tags/test","description":"Testing news"}],"readingTime":0.32,"hasTruncateMarker":true,"authors":[{"name":"Maxim","title":"Developer","url":"https://github.com/llOzzeell","page":{"permalink":"/mocpilot-app-docs/dk/blog/authors/maxim"},"socials":{"github":"https://github.com/llOzzeell"},"imageURL":"https://avatars.githubusercontent.com/u/45766241?v=4","key":"maxim"}],"frontMatter":{"title":"MOCPilot 2025.1.0","authors":["maxim"],"tags":["dev","test"]},"unlisted":false,"prevItem":{"title":"Udgivelse MOCPilot 2025.1.1","permalink":"/mocpilot-app-docs/dk/blog/2025/04/14/post"}},"content":"## \ud83d\ude80 MOCPilot 2025.1.0 Lukket Beta er begyndt!\\r\\n\\r\\nVi er begejstrede for at annoncere, at den lukkede beta-test for MOCPilot 2025 nu er live! Udvalgte brugere kan nu udforske nye funktioner, give feedback og v\xe6re med til at forme MOCPilot\' fremtid.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\nHvis du har modtaget en invitation, s\xe5 tjek din email for adgangsoplysninger.  \\r\\nTak fordi du er en del af denne vigtige fase!"}]}}')}}]);